#include <vector>
#include <cstddef>
#include <omp.h>

void relu(std::vector<double> &x) {
    const std::ptrdiff_t n = static_cast<std::ptrdiff_t>(x.size());

    #pragma omp parallel for default(none) shared(x, n) schedule(static)
    for (std::ptrdiff_t i = 0; i < n; ++i) {
        if (x[static_cast<std::size_t>(i)] < 0.0) {
            x[static_cast<std::size_t>(i)] = 0.0;
        }
    }
}
